 RETURNS TABLE(score numeric, spin_chances integer, cash_balance integer, score_updated_at timestamp with time zone, wheel_updated_at timestamp with time zone, score_log_id bigint, wheel_log_id bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
